import{_ as a,o as t,c as i,ae as r}from"./chunks/framework.DPZ3sAUK.js";const h=JSON.parse('{"title":"Runnable examples","description":"","frontmatter":{},"headers":[],"relativePath":"use-cases/runnable-examples.md","filePath":"use-cases/runnable-examples.md"}'),l={name:"use-cases/runnable-examples.md"};function o(s,e,n,c,u,p){return t(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="runnable-examples" tabindex="-1">Runnable examples <a class="header-anchor" href="#runnable-examples" aria-label="Permalink to &quot;Runnable examples&quot;">​</a></h1><p><code>neuron-js</code> includes first-party examples that can be executed from a clean checkout. Each example keeps the rule definition, input context, expected output, and runner separate so developers and coding agents can inspect the full contract before changing code.</p><h2 id="run-all-examples" tabindex="-1">Run all examples <a class="header-anchor" href="#run-all-examples" aria-label="Permalink to &quot;Run all examples&quot;">​</a></h2><p>From the repository root:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">yarn</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples</span></span></code></pre></div><p>The command builds the package, then runs:</p><ul><li><code>examples/pricing-rules/run.ts</code></li><li><code>examples/eligibility-check/run.ts</code></li><li><code>examples/workflow-routing/run.ts</code></li></ul><p>Each runner exits with a non-zero status if the actual output differs from <code>expected-output.json</code>.</p><h2 id="example-catalog" tabindex="-1">Example catalog <a class="header-anchor" href="#example-catalog" aria-label="Permalink to &quot;Example catalog&quot;">​</a></h2><h3 id="pricing-rules" tabindex="-1">Pricing rules <a class="header-anchor" href="#pricing-rules" aria-label="Permalink to &quot;Pricing rules&quot;">​</a></h3><p>Path: <a href="https://github.com/SebaSOFT/neuron-js/tree/main/examples/pricing-rules" target="_blank" rel="noreferrer"><code>examples/pricing-rules/</code></a></p><p>Demonstrates a cart-pricing decision stored as JSON. The script checks a cart subtotal and applies a VIP discount through a registered action.</p><p>Files:</p><ul><li><code>rules.json</code> — serializable script.</li><li><code>input.json</code> — execution context.</li><li><code>expected-output.json</code> — verified output summary.</li><li><code>run.ts</code> — executable TypeScript runner.</li></ul><h3 id="eligibility-check" tabindex="-1">Eligibility check <a class="header-anchor" href="#eligibility-check" aria-label="Permalink to &quot;Eligibility check&quot;">​</a></h3><p>Path: <a href="https://github.com/SebaSOFT/neuron-js/tree/main/examples/eligibility-check" target="_blank" rel="noreferrer"><code>examples/eligibility-check/</code></a></p><p>Demonstrates an approval decision. The script checks an applicant score and writes an approved eligibility decision into context.</p><p>Files:</p><ul><li><code>rules.json</code> — serializable script.</li><li><code>input.json</code> — execution context.</li><li><code>expected-output.json</code> — verified output summary.</li><li><code>run.ts</code> — executable TypeScript runner.</li></ul><h3 id="workflow-routing" tabindex="-1">Workflow routing <a class="header-anchor" href="#workflow-routing" aria-label="Permalink to &quot;Workflow routing&quot;">​</a></h3><p>Path: <a href="https://github.com/SebaSOFT/neuron-js/tree/main/examples/workflow-routing" target="_blank" rel="noreferrer"><code>examples/workflow-routing/</code></a></p><p>Demonstrates deterministic routing for automation workflows. The script checks ticket priority and assigns an escalation route with an SLA.</p><p>Files:</p><ul><li><code>rules.json</code> — serializable script.</li><li><code>input.json</code> — execution context.</li><li><code>expected-output.json</code> — verified output summary.</li><li><code>run.ts</code> — executable TypeScript runner.</li></ul><h2 id="why-this-structure" tabindex="-1">Why this structure <a class="header-anchor" href="#why-this-structure" aria-label="Permalink to &quot;Why this structure&quot;">​</a></h2><p>The examples are intentionally data-first:</p><ul><li>JSON rule files can be stored, versioned, reviewed, or generated.</li><li>Input files make scenario testing repeatable.</li><li>Expected outputs define a clear contract for humans and AI coding agents.</li><li>TypeScript runners show the minimal registry setup required by each scenario.</li></ul>',27)])])}const m=a(l,[["render",o]]);export{h as __pageData,m as default};
